namespace FclEx.Redis;public interface IRedisSortedSet : IRedisCollection{    Task<long> ZCardAsync();    Task<long> ZCountAsync(double min, double max);    Task<long> ZLexCountAsync(string min, string max);}public interface IRedisSortedSet<T> : IRedisSortedSet, IRedisCollection<T> where T : notnull{    Task<long> ZAddAsync(Dictionary<T, double> cacheValues);    Task<List<T>> ZRangeAsync(long start, long stop);    Task<long?> ZRankAsync(T cacheValue);    Task<long> ZRemAsync(IList<T> cacheValues);    Task<double?> ZScoreAsync(T cacheValue);}